import{_ as i,a as e,c as a,ac as r}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第七号嫌疑人","description":"第七号嫌疑人的主持流程、阶段提示和物料清单","frontmatter":{"title":"第七号嫌疑人","description":"第七号嫌疑人的主持流程、阶段提示和物料清单","sources":[{"repository":"jekyall_blog","file":"_posts/Cc/Left/2023-06-15-Suspect number seven.md","date":"Tue Jun 13 2023 12:48:54 GMT+0800 (中国标准时间)"}],"showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"生活记录","scope":"general","audience":"general","group":"学习与记录","summary":"第七号嫌疑人的主持流程、阶段提示和物料清单","status":"active","related":[{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"},{"title":"阿甘正传","link":"/life/personal/media/movies/forrest-gump","kind":"影视导读","scope":"general","audience":"general"},{"title":"把《周易》读进具体问题：乾坤、泰否、既济未济对读","link":"/life/personal/yijing/reading-practice","kind":"基础学习","scope":"general","audience":"general"}],"prev":false,"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":false},"headers":[],"relativePath":"life/personal/reading-games/suspect-number-seven.md","filePath":"life/personal/reading-games/suspect-number-seven.md"}'),t={name:"life/personal/reading-games/suspect-number-seven.md"};function n(s,l,o,u,c,d){return e(),a("div",null,[...l[0]||(l[0]=[r('<h1 id="第七号嫌疑人" tabindex="-1">第七号嫌疑人 <a class="header-anchor" href="#第七号嫌疑人" aria-label="Permalink to &quot;第七号嫌疑人&quot;">​</a></h1><p><span id="复盘"></span><span id="答疑"></span></p><h2 id="游戏步骤" tabindex="-1">游戏步骤 <a class="header-anchor" href="#游戏步骤" aria-label="Permalink to &quot;游戏步骤&quot;">​</a></h2><h3 id="前奏" tabindex="-1">前奏 <a class="header-anchor" href="#前奏" aria-label="Permalink to &quot;前奏&quot;">​</a></h3><ol><li>讲述剧本类型</li><li>讲述内容背景</li><li>选角色</li></ol><h3 id="游戏流程" tabindex="-1">游戏流程 <a class="header-anchor" href="#游戏流程" aria-label="Permalink to &quot;游戏流程&quot;">​</a></h3><ol><li>发放对应角色剧本，并阅读阅读到“请勿翻开下一页”</li><li>主持人提示：<strong>自己任务</strong></li></ol><h3 id="第一阶段" tabindex="-1">第一阶段 <a class="header-anchor" href="#第一阶段" aria-label="Permalink to &quot;第一阶段&quot;">​</a></h3><h4 id="第一幕-10-15" tabindex="-1">第一幕（10-15） <a class="header-anchor" href="#第一幕-10-15" aria-label="Permalink to &quot;第一幕（10-15）&quot;">​</a></h4><ul><li>发放线索卡和地图 <ul><li>给角色发放对应角色名字线索卡 * 6</li><li>地图 * 4 <ul><li>一楼平面图</li><li>二楼平面图</li><li>三楼平面图</li><li>四楼阁楼</li></ul></li></ul></li><li>讨论时间 <ul><li>自我介绍</li><li>分享自己唯一线索</li></ul></li><li>讨论结束 <ul><li>可以阅读下个阶段</li><li>给播放视频-01</li><li>第二幕开始</li></ul></li></ul><h4 id="第二幕-45-60" tabindex="-1">第二幕 (45-60) <a class="header-anchor" href="#第二幕-45-60" aria-label="Permalink to &quot;第二幕 (45-60)&quot;">​</a></h4><ul><li>去教堂说秘密（阅读）</li><li>讨论结束后</li><li>继续阅读</li><li>播放视频-02</li><li>直接进入第三幕</li></ul><h4 id="第三幕-10-15" tabindex="-1">第三幕（10-15） <a class="header-anchor" href="#第三幕-10-15" aria-label="Permalink to &quot;第三幕（10-15）&quot;">​</a></h4><ul><li>投票（洪先生该不该死）</li><li>投票记录 <ul><li>全部人闭上眼睛</li><li>该死 比手势</li><li>不该死 不动</li></ul></li><li>投票记录保存好，</li><li>公布总结果（无需要给出细节）</li></ul><h4 id="进入第四幕-45-60" tabindex="-1">进入第四幕（45-60） <a class="header-anchor" href="#进入第四幕-45-60" aria-label="Permalink to &quot;进入第四幕（45-60）&quot;">​</a></h4><ul><li>发放线索 <ul><li>阅读时 发放 “地下平面图” * 1</li><li>在搜索证时 发放线索卡 * 10</li></ul></li><li>给出密码<strong>9426936</strong></li><li>发放线索卡（阁楼密室）* 7</li></ul><h3 id="第二阶段-90" tabindex="-1">第二阶段（90） <a class="header-anchor" href="#第二阶段-90" aria-label="Permalink to &quot;第二阶段（90）&quot;">​</a></h3><h4 id="开始" tabindex="-1">开始 <a class="header-anchor" href="#开始" aria-label="Permalink to &quot;开始&quot;">​</a></h4><ul><li>李察不需要直接翻开下一幕</li><li>第二套剧本直接阅读</li><li>读完之后直接告诉、现在时间 2020-5-18</li><li>重新自我介绍</li><li>发放线索 <ul><li>白色资料卡 * 6</li><li>516 金秤拍卖行结案相关资料</li></ul></li><li>允许私聊和公聊，不限制</li><li>玩家遇到瓶颈，发放提示（酌情考虑）* 8</li></ul><h4 id="结束" tabindex="-1">结束 <a class="header-anchor" href="#结束" aria-label="Permalink to &quot;结束&quot;">​</a></h4><ul><li>给出答案/玩家自行决定什么时候给出答案 <ul><li>5 个题目 <ul><li>1 分</li><li>1 分</li><li>1 分</li><li>1 分</li><li>3 分</li></ul></li></ul></li><li>公布结果，给每个玩家计算分数发布</li></ul><h3 id="复盘与答疑" tabindex="-1">复盘与答疑 <a class="header-anchor" href="#复盘与答疑" aria-label="Permalink to &quot;复盘与答疑&quot;">​</a></h3><p>原笔记未记录具体复盘内容与问题答案。</p><h3 id="隐藏阶段-30" tabindex="-1">隐藏阶段（30） <a class="header-anchor" href="#隐藏阶段-30" aria-label="Permalink to &quot;隐藏阶段（30）&quot;">​</a></h3><ul><li>是否开启 <ul><li>必须：玩家提问”是谁在第二通电话结束后删除的播放记录和通话记录“</li></ul></li><li>主持人也可以引导开启（提问） <ul><li>过场剧情文字宣读</li><li>给出红色调查卡 * 5</li></ul></li><li>阶段任务 <ul><li>凶手是谁</li><li>动机是什么</li><li>杀人时间范围</li></ul></li><li>复盘</li></ul><h3 id="大结局" tabindex="-1">大结局 <a class="header-anchor" href="#大结局" aria-label="Permalink to &quot;大结局&quot;">​</a></h3><blockquote><p>宣读文本</p></blockquote><h2 id="suspect-number-seven" tabindex="-1">Suspect number seven <a class="header-anchor" href="#suspect-number-seven" aria-label="Permalink to &quot;Suspect number seven&quot;">​</a></h2><blockquote><p>全部内容</p></blockquote><ul><li>主持人手册 *1</li><li>音频 *2</li><li>结案相关资料 *1</li><li>剧本 <ul><li>1 *6</li><li>2 *5</li></ul></li><li>线索卡 *42 <ul><li>第一阶段嫌疑人 *6</li><li>线索卡（密室阁楼） *7</li><li>灰色线索卡 *10</li><li>附加提示卡 *8</li><li>红色调查资料 *5</li><li>灰色调查资料 *6</li></ul></li><li>音频 <ul><li><a href="/sources/jekyall_blog/assets/img/cc/script-killing/Suspect-number-seven-01.mp4">01 音视频</a></li><li><a href="/sources/jekyall_blog/assets/img/cc/script-killing/Suspect-number-seven-02.mp4">02 音视频</a></li></ul></li></ul>',30)])])}const b=i(t,[["render",n]]);export{p as __pageData,b as default};
